function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  erpUrl: 'https://httpbin.org/post',
  crmUrl: 'https://httpbin.org/post',
  verifyUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  allowSimulation: true
};

const hook = ref('Webhook - Master Data Change');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const entityType = String(body.entityType || body.type || '').toLowerCase();
if (!['customer', 'vendor'].includes(entityType)) errors.push('entityType must be customer or vendor');

const externalId = String(body.externalId || body.id || '').trim();
const name = String(body.name || body.companyName || body.legalName || '').trim();
const taxId = String(body.taxId || body.vatId || body.ein || '').trim();
const email = String(body.email || body.primaryEmail || '').trim().toLowerCase();
const country = String(body.country || body.countryCode || '').trim().toUpperCase();
const sourceSystem = String(body.sourceSystem || body.source || 'unknown').trim();

if (!name) errors.push('name / companyName is required');
if (!externalId && !taxId && !email) errors.push('at least one of externalId, taxId or email is required');

const valid = errors.length === 0;

const canonical = {
  entityType,
  externalId: externalId || null,
  name,
  taxId: taxId || null,
  email: email || null,
  phone: body.phone ? String(body.phone).trim() : null,
  address: body.address || null,
  country: country || null,
  status: String(body.status || 'active').toLowerCase(),
  sourceSystem,
  lastUpdated: new Date().toISOString()
};

let erpUrl = CONFIG.erpUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  erpUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    canonical,
    raw: body,
    urls: {
      erp: erpUrl,
      crm: CONFIG.crmUrl,
      verify: CONFIG.verifyUrl
    },
    requestId: body.requestId || ('mds-' + Date.now())
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Validate & Normalize');
const c = ctx.canonical;

// Simulated golden-record store (in real life this would be a DB lookup)
// Matching priority: taxId → externalId → email → fuzzy name
let matchType = 'none';
let goldenId = null;
let confidence = 0;
let existing = null;

if (c.taxId) {
  matchType = 'taxId';
  goldenId = 'GOLD-' + c.entityType.toUpperCase() + '-' + c.taxId.replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  confidence = 0.98;
  existing = { goldenId, name: c.name, taxId: c.taxId, email: c.email, status: 'active' };
} else if (c.externalId) {
  matchType = 'externalId';
  goldenId = 'GOLD-' + c.entityType.toUpperCase() + '-' + c.externalId;
  confidence = 0.92;
  existing = { goldenId, name: c.name, externalId: c.externalId, email: c.email, status: 'active' };
} else if (c.email) {
  matchType = 'email';
  goldenId = 'GOLD-' + c.entityType.toUpperCase() + '-' + c.email.split('@')[0].toUpperCase();
  confidence = 0.85;
  existing = { goldenId, name: c.name, email: c.email, status: 'active' };
} else {
  matchType = 'new';
  goldenId = 'GOLD-' + c.entityType.toUpperCase() + '-' + Date.now();
  confidence = 1.0;
  existing = null;
}

const isNew = matchType === 'new' || !existing;

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    canonical: c,
    urls: ctx.urls,
    match: {
      matchType,
      goldenId,
      confidence,
      isNew,
      existing
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Match & Deduplicate');
const incoming = ctx.canonical;
const existing = ctx.match.existing;

const conflicts = [];
const resolved = { ...incoming, goldenId: ctx.match.goldenId };

if (existing && !ctx.match.isNew) {
  const fieldsToCheck = ['name', 'email', 'taxId', 'phone', 'country', 'status'];
  for (const f of fieldsToCheck) {
    const inVal = incoming[f];
    const exVal = existing[f];
    if (inVal && exVal && String(inVal).toLowerCase() !== String(exVal).toLowerCase()) {
      conflicts.push({
        field: f,
        incoming: inVal,
        existing: exVal,
        resolution: 'prefer_incoming'
      });
      // simple policy: prefer incoming for this demo
      resolved[f] = inVal;
    }
  }
}

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    canonical: incoming,
    urls: ctx.urls,
    match: ctx.match,
    conflicts,
    resolved,
    hasConflicts: conflicts.length > 0
  }
}];

