const ctx = ref('Code - Detect Conflicts');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const ok = status >= 200 && status < 300;

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    urls: ctx.urls,
    match: ctx.match,
    conflicts: ctx.conflicts,
    resolved: ctx.resolved,
    sync: {
      erp: { ok, status }
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process ERP Result');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const ok = status >= 200 && status < 300;

const sync = {
  ...ctx.sync,
  crm: { ok, status }
};

return [{
  json: {
    requestId: ctx.requestId,
    config: ctx.config,
    urls: ctx.urls,
    match: ctx.match,
    conflicts: ctx.conflicts,
    resolved: ctx.resolved,
    sync
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Process CRM Result');
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;
const verifyOk = status >= 200 && status < 300;

const syncOk = (ctx.sync.erp?.ok !== false) && (ctx.sync.crm?.ok !== false);
const overall = syncOk && verifyOk ? 'synced' : (syncOk ? 'synced_unverified' : 'partial_failure');

const report = {
  requestId: ctx.requestId,
  goldenId: ctx.resolved.goldenId,
  entityType: ctx.resolved.entityType,
  name: ctx.resolved.name,
  match: {
    type: ctx.match.matchType,
    confidence: ctx.match.confidence,
    isNew: ctx.match.isNew
  },
  conflicts: ctx.conflicts,
  conflictCount: (ctx.conflicts || []).length,
  sync: ctx.sync,
  verification: { ok: verifyOk, status },
  overallStatus: overall,
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    requestId: ctx.requestId,
    report,
    overallStatus: overall
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const ctx = ref('Code - Build Sync Report');

const httpStatus = ctx.overallStatus === 'synced' ? 200 : (ctx.overallStatus === 'synced_unverified' ? 202 : 207);

const body = {
  status: ctx.overallStatus,
  requestId: ctx.requestId,
  report: ctx.report
};

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.requestId
  }
}];
